--
-- Name: calib_settings_candidates(integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: madi_results; Owner: -
--

CREATE FUNCTION madi_results.calib_settings_candidates(p_project integer, p_study character varying, p_experiment character varying, p_feature character varying, p_antigen character varying) RETURNS TABLE(param_name text, param_data_type text, param_integer_value integer, param_numeric_value numeric, param_boolean_value boolean, param_character_value text, tier_rank integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT s.param_name, s.param_data_type,
         s.param_integer_value, s.param_numeric_value,
         s.param_boolean_value, s.param_character_value,
         -- rank by how specific the matched tier is (5 = full key ... 0 = system)
         CASE
           WHEN s.project_id <> -1 AND s.study_accession <> '__none__'
             AND s.experiment_accession <> '__none__' AND s.feature <> '__none__'
             AND s.antigen <> '__none__'                                   THEN 5
           WHEN s.project_id <> -1 AND s.study_accession <> '__none__'
             AND s.experiment_accession <> '__none__' AND s.feature <> '__none__' THEN 4
           WHEN s.project_id <> -1 AND s.study_accession <> '__none__'
             AND s.experiment_accession <> '__none__'                      THEN 3
           WHEN s.project_id <> -1 AND s.study_accession <> '__none__'     THEN 2
           WHEN s.project_id <> -1                                         THEN 1
           ELSE 0   -- __system__
         END AS tier_rank
    FROM madi_results.calib_settings s
   WHERE (s.project_id           = p_project    OR s.project_id           = -1)
     AND (s.study_accession      = p_study      OR s.study_accession      = '__none__')
     AND (s.experiment_accession = p_experiment OR s.experiment_accession = '__none__')
     AND (s.feature              = p_feature    OR s.feature              = '__none__')
     AND (s.antigen              = p_antigen    OR s.antigen              = '__none__')
$$;


--
-- Name: madi_multiplate_group_id(integer, text, text, text, text, text, text, text); Type: FUNCTION; Schema: madi_results; Owner: -
--

CREATE FUNCTION madi_results.madi_multiplate_group_id(p_project_id integer, p_study text, p_experiment text, p_nominal text, p_source text, p_wavelength text, p_antigen text, p_feature text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT md5(
    array_to_string(ARRAY[
      COALESCE(p_project_id::text, '__none__'),
      COALESCE(p_study,            '__none__'),
      COALESCE(p_experiment,       '__none__'),
      COALESCE(p_nominal,          '__none__'),
      COALESCE(p_source,           '__none__'),
      COALESCE(p_wavelength,       '__none__'),
      COALESCE(p_antigen,          '__none__'),
      COALESCE(p_feature,          '__none__')
    ], '|')            -- '|' separator so adjacent fields cannot run together
  )::uuid
$$;


--
-- Name: resolve_settings(integer, character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: madi_results; Owner: -
--

CREATE FUNCTION madi_results.resolve_settings(p_project integer, p_study character varying, p_experiment character varying, p_feature character varying, p_antigen character varying) RETURNS TABLE(param_name text, param_data_type text, value_text text, tier_rank integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT DISTINCT ON (c.param_name)
         c.param_name, c.param_data_type,
         CASE c.param_data_type
           WHEN 'integer'   THEN c.param_integer_value::text
           WHEN 'numeric'   THEN c.param_numeric_value::text
           WHEN 'boolean'   THEN c.param_boolean_value::text
           WHEN 'character' THEN c.param_character_value
         END AS value_text,
         c.tier_rank
    FROM madi_results.calib_settings_candidates(
           p_project, p_study, p_experiment, p_feature, p_antigen) c
   ORDER BY c.param_name, c.tier_rank DESC
$$;


--
-- Name: resolve_settings_batch(bigint[]); Type: FUNCTION; Schema: madi_results; Owner: -
--

CREATE FUNCTION madi_results.resolve_settings_batch(p_curve_ids bigint[]) RETURNS TABLE(curve_id bigint, param_name text, param_data_type text, value_text text, tier_rank integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT cl.curve_id, r.param_name, r.param_data_type, r.value_text, r.tier_rank
    FROM madi_results.curve_lookup cl
    CROSS JOIN LATERAL madi_results.resolve_settings(
        COALESCE(cl.project_id, -1),
        COALESCE(cl.study_accession, '__none__'),
        COALESCE(cl.experiment_accession, '__none__'),
        COALESCE(cl.feature, '__none__'),
        COALESCE(cl.antigen, '__none__')) r
   WHERE cl.curve_id = ANY(p_curve_ids)
$$;


--
-- Name: trg_set_multiplate_group_id(); Type: FUNCTION; Schema: madi_results; Owner: -
--

CREATE FUNCTION madi_results.trg_set_multiplate_group_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.multiplate_group_id := madi_results.madi_multiplate_group_id(
        NEW.project_id,
        NEW.study_accession,
        NEW.experiment_accession,
        NEW.nominal_sample_dilution,
        NEW.source,
        NEW.wavelength,
        NEW.antigen,
        NEW.feature
    );
    RETURN NEW;
END;
$$;


