--
-- Name: blank_for_fit; Type: VIEW; Schema: madi_results; Owner: -
--

CREATE VIEW madi_results.blank_for_fit AS
 SELECT cl.curve_id,
    cl.multiplate_group_id,
    b.project_id,
    b.study_accession,
    b.experiment_accession,
    cl.antigen,
    cl.feature,
    cl.source,
    cl.wavelength,
    cl.nominal_sample_dilution,
    b.plate,
    b.plateid,
    b.well,
    b.source AS blank_source,
    b.antibody_mfi AS mfi,
    b.antibody_n,
    COALESCE(b.masked, false) AS masked,
    b.mask_reason
   FROM (madi_results.xmap_buffer b
     JOIN madi_results.curve_lookup cl ON (((cl.project_id = b.project_id) AND ((cl.study_accession)::text = (b.study_accession)::text) AND ((cl.experiment_accession)::text = (b.experiment_accession)::text) AND ((cl.plateid)::text = (b.plateid)::text) AND ((cl.plate)::text = (b.plate)::text) AND ((cl.nominal_sample_dilution)::text = (b.nominal_sample_dilution)::text) AND ((cl.wavelength)::text = (COALESCE(b.wavelength, '__none__'::character varying))::text) AND ((cl.antigen)::text = (COALESCE(b.antigen, '__none__'::character varying))::text) AND ((cl.feature)::text = (COALESCE(b.feature, '__none__'::character varying))::text) AND (cl.masked = false))));


