--
-- Name: sample_for_fit; Type: VIEW; Schema: madi_results; Owner: -
--

CREATE VIEW madi_results.sample_for_fit AS
 SELECT cl.curve_id,
    cl.multiplate_group_id,
    s.project_id,
    s.study_accession,
    s.experiment_accession,
    cl.antigen,
    cl.feature,
    cl.source,
    cl.wavelength,
    cl.nominal_sample_dilution,
    s.plate,
    s.plateid,
    s.well,
    s.sampleid,
    s.patientid,
