    s.well,
    s.dilution,
    s.antibody_mfi AS mfi,
    s.antibody_n,
    COALESCE(s.masked, false) AS masked,
    s.mask_reason
   FROM (madi_results.xmap_standard s
     JOIN madi_results.curve_lookup cl ON (((cl.project_id = s.project_id) AND ((cl.study_accession)::text = (s.study_accession)::text) AND ((cl.experiment_accession)::text = (s.experiment_accession)::text) AND ((cl.plateid)::text = (s.plateid)::text) AND ((cl.plate)::text = (s.plate)::text) AND ((cl.nominal_sample_dilution)::text = (s.nominal_sample_dilution)::text) AND ((cl.source)::text = (COALESCE(s.source, '__none__'::character varying))::text) AND ((cl.wavelength)::text = (COALESCE(s.wavelength, '__none__'::character varying))::text) AND ((cl.antigen)::text = (COALESCE(s.antigen, '__none__'::character varying))::text) AND ((cl.feature)::text = (COALESCE(s.feature, '__none__'::character varying))::text) AND (cl.masked = false))));


